  let shaded = 0;
  const samples = [];

  for (const f of scene.courts) {
    // court-local (a, b) -> world [x, y]
    for (let a = -f.pl / 2 + 0.6; a <= f.pl / 2; a += 1.4) {
      for (let b = -f.pw / 2 + 0.5; b <= f.pw / 2; b += 1.4) {
        const [px0, py0] = fromFrame(f, a, b);
        const world = [px0, py0];
        samples.push(world);
      }
    }
    // court -> samples index offset for this court
    const courtSamples = [];
    for (let a = -f.pl / 2 + 0.6; a <= f.pl / 2; a += 1.4) {
      for (let b = -f.pw / 2 + 0.5; b <= f.pw / 2; b += 1.4) {
        const [px0, py0] = fromFrame(f, a, b);
        courtSamples.push([px0, py0]);
      }
    }
    // add samples to the full set
    for (const [px0, py0] of courtSamples) {
